<?php
declare(strict_types=1);require __DIR__.'/app/marketplace-negotiation.php';header('Cache-Control: no-store, private');$destination='marketplace';
try{if($_SERVER['REQUEST_METHOD']!=='POST')throw new DomainException('Use POST to save marketplace items.',405);$user=require_verified();verify_csrf();$entity=marketplace_enum($_POST,'entity',['listing','request']);$id=marketplace_text($_POST,'id',36,true);$return=(string)($_POST['return_to']??'marketplace');if($return!==''&&!preg_match('/^[a-zA-Z0-9][a-zA-Z0-9?&=_-]*$/',$return))$return='marketplace';$destination=$return?:'marketplace';if($entity==='listing'){$saved=marketplace_toggle_save($user,$id);}else{$request=request_public($id);if($request['organization_id']===$user['owner_id'])throw new DomainException('Your own request is already available in Procurement.',409);$saved=(bool)rows('SELECT 1 FROM marketplace_saved_requests WHERE user_id=? AND request_id=?',[$user['id'],$id]);if($saved){db()->prepare('DELETE FROM marketplace_saved_requests WHERE user_id=? AND request_id=?')->execute([$user['id'],$id]);$saved=false;}else{db()->prepare('INSERT INTO marketplace_saved_requests(user_id,request_id) VALUES(?,?)')->execute([$user['id'],$id]);$saved=true;}}flash('success',$saved?'Saved to your marketplace items.':'Removed from your saved marketplace items.');redirect($destination);}catch(Throwable $error){flash('error',$error instanceof DomainException?$error->getMessage():'The marketplace item could not be saved.');redirect($destination);}
